package tacc

import java.io.File
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals

/** Generated bytecode: exact instruction sequences, and behavior on the reference interpreter. */
class CodeGenTest {
    private fun code(source: String, function: String = "main"): List<String> =
        disassemble(Module.read(compile(source)), function)

    // ---- Exact bytecode ----

    @Test
    fun helloMatchesTheHandAssembledReference() {
        val reference = File("../tests/hello/hello.bc").readBytes()
        assertContentEquals(reference, compile(File("../tests/hello/hello.tc").readText()))
    }

    @Test
    fun localsUseSlotsAfterParameters() {
        val module = Module.read(compile("fun f(a: Int, b: Int): Int { let c = a + b; return c; }\nfun main() { }"))
        val f = module.functions.first { it.name == "f" }
        assertEquals(2, f.paramCount)
        assertEquals(1, f.localCount)
        assertEquals(
            listOf("0 LOAD 0", "2 LOAD 1", "4 ADD", "5 STORE 2", "7 LOAD 2", "9 RET"),
            disassemble(module, "f"),
        )
    }

    @Test
    fun comparisonsAreLoweredPerCompilationNotes() {
        fun cmp(op: String) =
            code("fun f(a: Int, b: Int): Bool { return a $op b; }\nfun main() { }", "f")
                .map { it.substringAfter(' ') }
        assertEquals(listOf("LOAD 0", "LOAD 1", "CMP_LT", "RET"), cmp("<"))
        assertEquals(listOf("LOAD 1", "LOAD 0", "CMP_LT", "RET"), cmp(">"))
        assertEquals(listOf("LOAD 1", "LOAD 0", "CMP_LT", "NOT", "RET"), cmp("<="))
        assertEquals(listOf("LOAD 0", "LOAD 1", "CMP_LT", "NOT", "RET"), cmp(">="))
        assertEquals(listOf("LOAD 0", "LOAD 1", "CMP_EQ", "RET"), cmp("=="))
        assertEquals(listOf("LOAD 0", "LOAD 1", "CMP_EQ", "NOT", "RET"), cmp("!="))
    }

    @Test
    fun unaryOperatorsAndBooleans() {
        assertEquals(
            listOf(
                "0 PUSH_CONST 0", "3 PUSH_CONST 5", "6 SUB", "7 STORE 0",
                "9 PUSH_CONST 1", "12 NOT", "13 STORE 1",
                "15 PUSH_CONST 0", "18 RET",
            ),
            code("fun main() { let n = -5; let b = !true; }"),
        )
    }

    @Test
    fun whileLoopJumps() {
        assertEquals(
            listOf(
                "0 PUSH_CONST 0", "3 STORE 0",
                "5 LOAD 0", "7 PUSH_CONST 3", "10 CMP_LT", "11 JMP_IF_FALSE 29",
                "16 LOAD 0", "18 PUSH_CONST 1", "21 ADD", "22 STORE 0", "24 JMP 5",
                "29 PUSH_CONST 0", "32 RET",
            ),
            code("fun main() { let i = 0; while (i < 3) { i = i + 1; } }"),
        )
    }

    @Test
    fun ifElseJumps() {
        assertEquals(
            listOf(
                "0 PUSH_CONST 1", "3 JMP_IF_FALSE 21",
                "8 PUSH_CONST \"yes\"", "11 CALL_RUNTIME runtime.log, 1", "15 POP", "16 JMP 29",
                "21 PUSH_CONST \"no\"", "24 CALL_RUNTIME runtime.log, 1", "28 POP",
                "29 PUSH_CONST 0", "32 RET",
            ),
            code("fun main() { if (true) { runtime.log(\"yes\"); } else { runtime.log(\"no\"); } }"),
        )
    }

    @Test
    fun noJumpToTheEndOfCodeWhenBothBranchesReturn() {
        assertEquals(
            listOf(
                "0 LOAD 0", "2 PUSH_CONST 0", "5 CMP_LT", "6 JMP_IF_FALSE 15",
                "11 PUSH_CONST 0", "14 RET",
                "15 LOAD 0", "17 RET",
            ),
            code("fun f(a: Int): Int { if (a < 0) { return 0; } else { return a; } }\nfun main() { }", "f"),
        )
    }

    @Test
    fun callsAndStatementPop() {
        assertEquals(
            listOf(
                "0 PUSH_CONST 2", "3 CALL twice, 1", "7 STORE 0",
                "9 PUSH_CONST 2", "12 CALL twice, 1", "16 POP",
                "17 PUSH_CONST 0", "20 RET",
            ),
            code("fun twice(n: Int): Int { return n * 2; }\nfun main() { let x = twice(2); twice(2); }"),
        )
    }

    // ---- Behavior on the reference interpreter ----

    @Test
    fun languageSpecExampleRuns() {
        // tests/language-example holds the example from spec/language.md -> "Examples" verbatim.
        val source = File("../tests/language-example/language-example.tc").readText()
        assertEquals(listOf("done"), run(source))
    }

    @Test
    fun integrationProgramRuns() {
        val source = File("../tests/control-flow/control-flow.tc").readText()
        val expected = File("../tests/control-flow/expected.txt").readLines()
        assertEquals(expected, run(source))
    }

    @Test
    fun arithmeticAndComparisons() {
        val source = """
            fun check(ok: Bool, name: String) {
                if (ok) { runtime.log(name); } else { runtime.log("FAIL"); runtime.log(name); }
            }
            fun main() {
                check(7 - 2 - 1 == 4, "left-assoc minus");
                check(2 + 3 * 4 == 14, "precedence");
                check((2 + 3) * 4 == 20, "parentheses");
                check(7 / 2 == 3, "integer division");
                check(-7 + 10 == 3, "unary minus");
                check(3 > 2, "gt");
                check(!(2 > 3), "not gt");
                check(2 <= 2, "le equal");
                check(!(3 <= 2), "le greater");
                check(2 >= 2, "ge");
                check(1 != 2, "ne");
                check("a" == "a", "string eq");
                check(true != false, "bool ne");
            }
        """
        assertEquals(
            listOf(
                "left-assoc minus", "precedence", "parentheses", "integer division", "unary minus",
                "gt", "not gt", "le equal", "le greater", "ge", "ne", "string eq", "bool ne",
            ),
            run(source),
        )
    }

    @Test
    fun recursionAndShadowing() {
        val source = """
            fun fact(n: Int): Int {
                if (n <= 1) { return 1; }
                return n * fact(n - 1);
            }
            fun main() {
                let x = fact(5);
                if (x == 120) {
                    let x = "shadowed";
                    runtime.log(x);
                }
                if (x == 120) { runtime.log("outer x kept"); }
            }
        """
        assertEquals(listOf("shadowed", "outer x kept"), run(source))
    }

    @Test
    fun elseIfChainAndEarlyReturn() {
        val source = """
            fun sign(n: Int): String {
                if (n < 0) { return "negative"; } else if (n == 0) { return "zero"; } else { return "positive"; }
            }
            fun main() {
                runtime.log(sign(-3));
                runtime.log(sign(0));
                runtime.log(sign(8));
                let i = 0;
                while (true) {
                    if (i == 2) { return; }
                    runtime.log("tick");
                    i = i + 1;
                }
            }
        """
        assertEquals(listOf("negative", "zero", "positive", "tick", "tick"), run(source))
    }
}
